const item = $input.first();
const body = item.json?.body ?? item.json ?? {};
const binaryKeys = Object.keys(item.binary ?? {});
const binaryKey = binaryKeys.length > 0 ? binaryKeys[0] : null;

function uuidv4() {
  if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.floor(Math.random() * 16);
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

const formularioId =
  body.formulario_id ??
  body.formularioId ??
  body.id ??
  null;

const pdfUrl =
  body.pdf_url ??
  body.url ??
  null;

let route = 'error';
if (binaryKey) route = 'file';
else if (pdfUrl) route = 'url';

return [{
  json: {
    route,
    formulario_id_origen: formularioId,
    pdf_url: pdfUrl,
    binary_key: binaryKey,
    transaction_id: uuidv4(),
    execution_started_at: new Date().toISOString(),
    execution_started_ms: Date.now()
  },
  binary: item.binary
}];

const item = $input.first();
const key = item.json.binary_key;

if (!key || !item.binary?.[key]) {
  throw new Error('No se encontró el archivo binario recibido por el Webhook.');
}

return [{
  json: item.json,
  binary: {
    data: item.binary[key]
  }
}];

function sha256Bytes(bytes) {
  function rightRotate(value, amount) {
    return (value >>> amount) | (value << (32 - amount));
  }

  const mathPow = Math.pow;
  const maxWord = mathPow(2, 32);
  let i, j;
  let result = '';
  const words = [];
  const byteLength = bytes.length;
  const bitLength = byteLength * 8;
  const hash = [];
  const k = [];
  let primeCounter = 0;
  const isComposite = {};

  for (let candidate = 2; primeCounter < 64; candidate++) {
    if (!isComposite[candidate]) {
      for (i = 0; i < 313; i += candidate) isComposite[i] = candidate;
      hash[primeCounter] = (mathPow(candidate, 0.5) * maxWord) | 0;
      k[primeCounter++] = (mathPow(candidate, 1 / 3) * maxWord) | 0;
    }
  }

  for (i = 0; i < byteLength; i++) {
    words[i >> 2] |= bytes[i] << ((3 - i) % 4) * 8;
  }

  words[bitLength >> 5] |= 0x80 << (24 - (bitLength % 32));
  words[(((bitLength + 64) >> 9) << 4) + 15] = bitLength;

  for (j = 0; j < words.length; ) {
    const w = words.slice(j, (j += 16));
    const oldHash = hash.slice(0);

    let a = hash[0], b = hash[1], c = hash[2], d = hash[3];
    let e = hash[4], f = hash[5], g = hash[6], h = hash[7];

    for (i = 0; i < 64; i++) {
      const w15 = w[i - 15], w2 = w[i - 2];
      const s0 = i < 16 ? 0 : (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3));
      const s1 = i < 16 ? 0 : (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10));
      const wi = i < 16 ? (w[i] | 0) : (w[i] = (((w[i - 16] | 0) + s0 + (w[i - 7] | 0) + s1) | 0));

      const S1 = rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25);
      const ch = (e & f) ^ (~e & g);
      const temp1 = (h + S1 + ch + k[i] + wi) | 0;
      const S0 = rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (S0 + maj) | 0;

      h = g; g = f; f = e; e = (d + temp1) | 0;
      d = c; c = b; b = a; a = (temp1 + temp2) | 0;
    }

    hash[0] = (oldHash[0] + a) | 0;
    hash[1] = (oldHash[1] + b) | 0;
    hash[2] = (oldHash[2] + c) | 0;
    hash[3] = (oldHash[3] + d) | 0;
    hash[4] = (oldHash[4] + e) | 0;
    hash[5] = (oldHash[5] + f) | 0;
    hash[6] = (oldHash[6] + g) | 0;
    hash[7] = (oldHash[7] + h) | 0;
  }

  for (i = 0; i < 8; i++) {
    for (j = 3; j + 1; j--) {
      const b = (hash[i] >> (j * 8)) & 255;
      result += (b < 16 ? '0' : '') + b.toString(16);
    }
  }

  return result;
}

const item = $input.first();
let buffer;

try {
  buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (e) {
  return [{
    json: {
      valid_document: false,
      validation_errors: ['no_se_pudo_leer_el_binario'],
      error_detail: e.message
    }
  }];
}

const binaryMeta = item.binary?.data ?? {};
const filename = binaryMeta.fileName || 'documento.pdf';
const mimeType = binaryMeta.mimeType || '';

const errors = [];

if (!buffer || buffer.length === 0) {
  errors.push('archivo_vacio');
}

const first5 = buffer.length >= 5 ? buffer.subarray(0, 5).toString('ascii') : '';
const isPdf = first5 === '%PDF-';
const isPng = buffer.length >= 8 &&
  buffer[0] === 0x89 && buffer[1] === 0x50 && buffer[2] === 0x4E && buffer[3] === 0x47;
const isJpg = buffer.length >= 3 &&
  buffer[0] === 0xFF && buffer[1] === 0xD8 && buffer[2] === 0xFF;

if (!(isPdf || isPng || isJpg)) {
  errors.push('firma_archivo_no_reconocida');
}

const acceptedMime = [
  'application/pdf',
  'image/png',
  'image/jpeg',
  'image/jpg',
  ''
];

if (!acceptedMime.includes(mimeType)) {
  errors.push('mime_no_permitido');
}

const bytes = new Uint8Array(buffer);
const sha256 = sha256Bytes(bytes);

return [{
  json: {
    valid_document: errors.length === 0,
    validation_errors: errors,
    formulario_id_origen: $('Preparar entrada').first().json.formulario_id_origen ?? null,
    filename,
    mime_type: mimeType || (isPdf ? 'application/pdf' : isPng ? 'image/png' : isJpg ? 'image/jpeg' : null),
    size_bytes: buffer.length,
    sha256,
    base64: buffer.toString('base64')
  },
  binary: item.binary
}];

const extracted = $input.first().json;
const meta = $('Validar + Base64 + SHA256').first().json;

const textoDocumento =
  extracted.text ??
  extracted.data ??
  extracted.content ??
  JSON.stringify(extracted);

const prompt = `
Extrae los datos del formulario UIF incluido abajo.

IMPORTANTE:
- Devuelve SOLO un objeto JSON válido.
- No uses markdown.
- No expliques nada.
- No devuelvas tipos como string|null, boolean|null o number.
- Reemplaza los null del ejemplo por el valor real SOLO cuando el dato esté claramente presente.
- Si un dato no aparece o no puede determinarse con claridad, deja null.
- No inventes información.
- No evalúes cumplimiento normativo ni determines si la operación es sospechosa.

La salida debe respetar EXACTAMENTE estas claves:

{
  "formulario_id": null,
  "cliente": {
    "nombre_completo": null,
    "tipo_documento": null,
    "numero_documento": null,
    "cuit_cuil": null,
    "domicilio": null
  },
  "operacion": {
    "fecha": null,
    "ticket": null,
    "maquina": null,
    "importe": null,
    "moneda": null,
    "medio_pago": null
  },
  "declaraciones": {
    "pep": null,
    "certificado_documentacion": null
  },
  "reportante": {
    "nombre": null
  }
}

Reglas de extracción:
- formulario_id = número del formulario.
- cliente.nombre_completo = nombres + apellidos del cliente.
- cliente.tipo_documento = DNI, CUIT, CUIL, PASAPORTE u OTRO.
- operacion.fecha = fecha de la operación reportada.
- operacion.importe = Importe Total del Pago cuando exista, sin símbolos de moneda.
- operacion.moneda = ARS si el documento está expresado en pesos argentinos.
- declaraciones.pep = valor indicado en Persona Expuesta Políticamente.
- declaraciones.certificado_documentacion = valor del campo Requiere Certificado.
- operacion.medio_pago solo se informa si está inequívocamente seleccionado.
- reportante.nombre = Nombre y Apellido del reportante.

TEXTO DEL DOCUMENTO:
--- INICIO ---
${textoDocumento}
--- FIN ---
`;

const requestBody = {
  model: "nvidia/nemotron-3.5-lightning-30b-a3b",
  messages: [
    {
      role: "user",
      content: prompt
    }
  ],
  response_format: {
    type: "json_object"
  },
  temperature: 0,
  top_p: 1,
  max_tokens: 1800,
  stream: false,
  chat_template_kwargs: {
    enable_thinking: false
  }
};

return [{
  json: {
    request_body: requestBody,
    metadata: {
      formulario_id_origen: meta.formulario_id_origen,
      filename: meta.filename,
      mime_type: meta.mime_type,
      size_bytes: meta.size_bytes,
      sha256: meta.sha256
    }
  }
}];

const response = $input.first().json;

if (response?.error) {
  return [{
    json: {
      api_ok: false,
      error_message: response.error.message || 'Error devuelto por NVIDIA.'
    }
  }];
}

let text = response?.choices?.[0]?.message?.content ?? null;

if (!text) {
  return [{
    json: {
      api_ok: false,
      error_message: 'NVIDIA respondió, pero no devolvió contenido.'
    }
  }];
}

text = String(text).trim();
text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();

const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start >= 0 && end > start) {
  text = text.slice(start, end + 1);
}

try {
  const extracted = JSON.parse(text);
  return [{
    json: {
      api_ok: true,
      extracted
    }
  }];
} catch (e) {
  return [{
    json: {
      api_ok: false,
      error_message: `La respuesta de NVIDIA no pudo convertirse a JSON: ${e.message}`,
      raw_preview: text.slice(0, 1000)
    }
  }];
}

function cleanString(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  return s === '' ? null : s;
}

function normalizeDocType(v) {
  const s = cleanString(v);
  if (!s) return null;
  const u = s.toUpperCase().replace(/\./g, '').trim();
  if (u.includes('DNI')) return 'DNI';
  if (u.includes('CUIT')) return 'CUIT';
  if (u.includes('CUIL')) return 'CUIL';
  if (u.includes('PASAP')) return 'PASAPORTE';
  return 'OTRO';
}

function normalizeDate(v) {
  const s = cleanString(v);
  if (!s) return null;

  const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return `${iso[1]}-${iso[2]}-${iso[3]}`;

  const ar = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})/);
  if (ar) {
    const dd = ar[1].padStart(2, '0');
    const mm = ar[2].padStart(2, '0');
    return `${ar[3]}-${mm}-${dd}`;
  }

  return null;
}

function normalizeAmount(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;

  let s = String(v)
    .replace(/\$/g, '')
    .replace(/\s/g, '')
    .replace(/[^\d,.\-]/g, '');

  if (!s) return null;

  if (s.includes(',') && s.includes('.')) {
    const lastComma = s.lastIndexOf(',');
    const lastDot = s.lastIndexOf('.');
    if (lastComma > lastDot) {
      s = s.replace(/\./g, '').replace(',', '.');
    } else {
      s = s.replace(/,/g, '');
    }
  } else if (s.includes(',')) {
    s = s.replace(/\./g, '').replace(',', '.');
  }

  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

function digitsOrNull(v) {
  const s = cleanString(v);
  if (!s) return null;
  const d = s.replace(/\D/g, '');
  return d || null;
}

const e = $input.first().json.extracted;
const meta = $('Construir payload NVIDIA').first().json.metadata;

const formularioId = cleanString(e.formulario_id) || cleanString(meta.formulario_id_origen);

const normalized = {
  formulario_id: formularioId,
  fecha_procesamiento: new Date().toISOString(),
  cliente: {
    nombre_completo: cleanString(e.cliente?.nombre_completo),
    tipo_documento: normalizeDocType(e.cliente?.tipo_documento),
    numero_documento: digitsOrNull(e.cliente?.numero_documento),
    cuit_cuil: digitsOrNull(e.cliente?.cuit_cuil),
    domicilio: cleanString(e.cliente?.domicilio)
  },
  operacion: {
    fecha: normalizeDate(e.operacion?.fecha),
    ticket: cleanString(e.operacion?.ticket),
    maquina: cleanString(e.operacion?.maquina),
    importe: normalizeAmount(e.operacion?.importe),
    moneda: cleanString(e.operacion?.moneda) || 'ARS',
    medio_pago: cleanString(e.operacion?.medio_pago)
  },
  declaraciones: {
    pep: typeof e.declaraciones?.pep === 'boolean' ? e.declaraciones.pep : null,
    certificado_documentacion:
      typeof e.declaraciones?.certificado_documentacion === 'boolean'
        ? e.declaraciones.certificado_documentacion
        : null
  },
  reportante: {
    nombre: cleanString(e.reportante?.nombre)
  },
  control: {
    documento_completo: false,
    requiere_revision: false,
    motivos_revision: [],
    confianza_extraccion: 0
  },
  archivo: {
    nombre_original: meta.filename,
    sha256: meta.sha256
  }
};

const critical = [
  ['formulario_id', normalized.formulario_id],
  ['cliente.nombre_completo', normalized.cliente.nombre_completo],
  ['cliente.tipo_documento', normalized.cliente.tipo_documento],
  ['cliente.numero_documento', normalized.cliente.numero_documento],
  ['operacion.fecha', normalized.operacion.fecha],
  ['operacion.importe', normalized.operacion.importe]
];

const missing = critical
  .filter(([, value]) => value === null || value === undefined || value === '')
  .map(([name]) => name);

normalized.control.documento_completo = missing.length === 0;
normalized.control.requiere_revision = missing.length > 0;
normalized.control.motivos_revision = missing.map(x => `campo_critico_faltante:${x}`);
normalized.control.confianza_extraccion =
  Number(((critical.length - missing.length) / critical.length).toFixed(2));

return [{
  json: {
    critical_ok: missing.length === 0 ? 'yes' : 'no',
    resultado: normalized
  }
}];

const src = $input.first().json.resultado;
const trace = $('Preparar entrada').first().json;

const has = v => !(v === null || v === undefined || v === '');
const safePayload = {
  schema_version: '1.0',
  formulario_id_present: has(src.formulario_id),
  cliente: {
    nombre_present: has(src.cliente?.nombre_completo),
    tipo_documento: src.cliente?.tipo_documento ?? null,
    numero_documento_present: has(src.cliente?.numero_documento),
    cuit_cuil_present: has(src.cliente?.cuit_cuil),
    domicilio_present: has(src.cliente?.domicilio)
  },
  operacion: {
    fecha: src.operacion?.fecha ?? null,
    ticket_present: has(src.operacion?.ticket),
    maquina_present: has(src.operacion?.maquina),
    importe_present: typeof src.operacion?.importe === 'number' && Number.isFinite(src.operacion.importe),
    importe_non_negative: typeof src.operacion?.importe === 'number' ? src.operacion.importe >= 0 : null,
    moneda: src.operacion?.moneda ?? null,
    medio_pago_present: has(src.operacion?.medio_pago)
  },
  declaraciones: {
    pep_informado: typeof src.declaraciones?.pep === 'boolean',
    certificado_documentacion_informado: typeof src.declaraciones?.certificado_documentacion === 'boolean'
  },
  reportante_present: has(src.reportante?.nombre),
  baseline_control: {
    documento_completo: Boolean(src.control?.documento_completo),
    requiere_revision: Boolean(src.control?.requiere_revision),
    motivos_revision: Array.isArray(src.control?.motivos_revision) ? src.control.motivos_revision : [],
    confianza_extraccion: Number(src.control?.confianza_extraccion ?? 0)
  },
  archivo: {
    sha256_present: /^[A-Fa-f0-9]{64}$/.test(src.archivo?.sha256 ?? ''),
    extension: String(src.archivo?.nombre_original ?? '').split('.').pop()?.toLowerCase() ?? null
  }
};

const config = {
  min_agent_confidence: 0.85,
  max_agent_latency_ms: 15000,
  max_execution_cost_usd: 0.50,
  input_usd_per_1m: 0,
  output_usd_per_1m: 0,
  max_agent_calls: 2,
  agent_model: 'nvidia/nemotron-3.5-lightning-30b-a3b',
  alert_webhook_url: 'CONFIGURAR_EN_N8N'
};

return [{
  json: {
    transaction_id: trace.transaction_id,
    execution_started_at: trace.execution_started_at,
    execution_started_ms: trace.execution_started_ms,
    resultado_original: src,
    safe_payload: safePayload,
    config,
    pii_removed: [
      'cliente.nombre_completo',
      'cliente.numero_documento',
      'cliente.cuit_cuil',
      'cliente.domicilio',
      'reportante.nombre',
      'operacion.importe',
      'operacion.ticket',
      'operacion.maquina',
      'texto_documento_original'
    ]
  }
}];

const s = $input.first().json;
const system = `Sos el Agente A - Analista de Integridad Documental UIF.
Tu función es evaluar calidad e integridad de datos YA EXTRAÍDOS y SANITIZADOS.
No decidís cumplimiento normativo, no clasificás operaciones sospechosas, no evaluás al cliente y no reemplazás a Cumplimiento.
No pidas ni infieras PII. No inventes campos. No uses conocimiento externo.
Si faltan campos críticos, hay inconsistencias o la confianza base es baja, marcá REVIEW.

Devolvé SOLO JSON válido con estas claves:
{
  "status": "OK|REVIEW",
  "quality_score": 0.0,
  "critical_issues": [],
  "warnings": [],
  "handoff_summary": "string"
}

quality_score debe estar entre 0 y 1.`;

const requestBody = {
  model: s.config.agent_model,
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: JSON.stringify(s.safe_payload) }
  ],
  response_format: { type: 'json_object' },
  temperature: 0,
  top_p: 1,
  max_tokens: 800,
  stream: false
};

return [{
  json: {
    ...s,
    agent_name: 'UIF_Analyst',
    agent_started_ms: Date.now(),
    request_body: requestBody
  }
}];

const response = $input.first().json;
const ctx = $('Construir Agente A').first().json;
const usage = response?.usage ?? {};
const inputTokens = Number(usage.prompt_tokens ?? usage.input_tokens ?? 0);
const outputTokens = Number(usage.completion_tokens ?? usage.output_tokens ?? 0);
const inputRate = Number(ctx.config.input_usd_per_1m ?? 0);
const outputRate = Number(ctx.config.output_usd_per_1m ?? 0);
const estimatedCost = (inputTokens / 1000000) * inputRate + (outputTokens / 1000000) * outputRate;
const latency = Date.now() - Number(ctx.agent_started_ms);

let agentStatus = 'Success';
let errorCode = null;
let result = null;

if (response?.error) {
  agentStatus = 'Fail';
  errorCode = 'AGENT_A_API_ERROR';
} else {
  let text = response?.choices?.[0]?.message?.content ?? '';
  text = String(text).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  try {
    result = JSON.parse(text);
  } catch {
    agentStatus = 'Fail';
    errorCode = 'AGENT_A_INVALID_JSON';
  }
}

if (agentStatus === 'Success') {
  const validStatus = ['OK','REVIEW'].includes(result?.status);
  const score = Number(result?.quality_score);
  if (!validStatus || !Number.isFinite(score) || score < 0 || score > 1) {
    agentStatus = 'Fail';
    errorCode = 'AGENT_A_INVALID_CONTRACT';
  }
}

const minConfidence = Number(ctx.config.min_agent_confidence);
const costConfigured = inputRate > 0 || outputRate > 0;
const overBudget = costConfigured && estimatedCost > Number(ctx.config.max_execution_cost_usd);

const proceed =
  agentStatus === 'Success' &&
  result?.status === 'OK' &&
  Number(result?.quality_score) >= minConfidence &&
  !overBudget;

return [{
  json: {
    transaction_id: ctx.transaction_id,
    timestamp_sql: new Date().toISOString().slice(0,23).replace('T',' '),
    agent_name: 'UIF_Analyst',
    agent_status: agentStatus,
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    estimated_cost_usd: Number(estimatedCost.toFixed(8)),
    cost_rate_configured: costConfigured,
    latency_ms: latency,
    error_code: errorCode,
    agent_result: result,
    proceed_to_agent_b: proceed ? 'yes' : 'no'
  }
}];

const s = $('Sanitizar PII + Trace').first().json;
const a = $('Parsear Agente A').first().json;

const system = `Sos el Agente B - Revisor y Enrutador Operativo UIF.
Recibís únicamente datos sanitizados y el resultado del Agente A.
Tu única decisión permitida es de CALIDAD DE DATOS:
- AUTO_CONTINUE: el registro puede continuar al siguiente paso técnico.
- HUMAN_REVIEW: una persona debe revisar la extracción.

No aprobás ni rechazás clientes. No determinás operación sospechosa. No emitís juicio de cumplimiento normativo.
Ante duda, inconsistencia, baja confianza o información crítica faltante, elegí HUMAN_REVIEW.
Devolvé SOLO JSON válido:
{
  "routing_decision": "AUTO_CONTINUE|HUMAN_REVIEW",
  "confidence": 0.0,
  "reasons": [],
  "required_human_action": "string|null"
}`;

const handoff = {
  sanitized_document: s.safe_payload,
  analyst_result: a.agent_result
};

const requestBody = {
  model: s.config.agent_model,
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: JSON.stringify(handoff) }
  ],
  response_format: { type: 'json_object' },
  temperature: 0,
  top_p: 1,
  max_tokens: 700,
  stream: false
};

return [{
  json: {
    transaction_id: s.transaction_id,
    config: s.config,
    agent_name: 'UIF_Reviewer',
    agent_started_ms: Date.now(),
    request_body: requestBody
  }
}];

const response = $input.first().json;
const ctx = $('Construir Agente B').first().json;
const usage = response?.usage ?? {};
const inputTokens = Number(usage.prompt_tokens ?? usage.input_tokens ?? 0);
const outputTokens = Number(usage.completion_tokens ?? usage.output_tokens ?? 0);
const inputRate = Number(ctx.config.input_usd_per_1m ?? 0);
const outputRate = Number(ctx.config.output_usd_per_1m ?? 0);
const estimatedCost = (inputTokens / 1000000) * inputRate + (outputTokens / 1000000) * outputRate;
const latency = Date.now() - Number(ctx.agent_started_ms);

let agentStatus = 'Success';
let errorCode = null;
let result = null;

if (response?.error) {
  agentStatus = 'Fail';
  errorCode = 'AGENT_B_API_ERROR';
} else {
  let text = response?.choices?.[0]?.message?.content ?? '';
  text = String(text).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  try {
    result = JSON.parse(text);
  } catch {
    agentStatus = 'Fail';
    errorCode = 'AGENT_B_INVALID_JSON';
  }
}

if (agentStatus === 'Success') {
  const validDecision = ['AUTO_CONTINUE','HUMAN_REVIEW'].includes(result?.routing_decision);
  const confidence = Number(result?.confidence);
  if (!validDecision || !Number.isFinite(confidence) || confidence < 0 || confidence > 1) {
    agentStatus = 'Fail';
    errorCode = 'AGENT_B_INVALID_CONTRACT';
  }
}

return [{
  json: {
    transaction_id: ctx.transaction_id,
    timestamp_sql: new Date().toISOString().slice(0,23).replace('T',' '),
    agent_name: 'UIF_Reviewer',
    agent_status: agentStatus,
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    estimated_cost_usd: Number(estimatedCost.toFixed(8)),
    cost_rate_configured: inputRate > 0 || outputRate > 0,
    latency_ms: latency,
    error_code: errorCode,
    agent_result: result
  }
}];

const s = $('Sanitizar PII + Trace').first().json;
const a = $('Parsear Agente A').first().json;
let b = null;
try { b = $('Parsear Agente B').first().json; } catch {}

const reasons = [];
const alerts = [];
const minConfidence = Number(s.config.min_agent_confidence);
const maxLatency = Number(s.config.max_agent_latency_ms);
const maxCost = Number(s.config.max_execution_cost_usd);

if (s.resultado_original.control?.requiere_revision) {
  reasons.push(...(s.resultado_original.control.motivos_revision ?? []));
}
if (a.agent_status !== 'Success') {
  reasons.push(a.error_code || 'agente_a_fallo');
  alerts.push('agent_a_failure');
} else {
  if (a.agent_result?.status !== 'OK') reasons.push(...(a.agent_result?.critical_issues ?? ['agente_a_requiere_revision']));
  if (Number(a.agent_result?.quality_score ?? 0) < minConfidence) reasons.push('agente_a_confianza_baja');
  if (a.latency_ms > maxLatency) alerts.push('agent_a_latency_threshold');
}

if (a.proceed_to_agent_b === 'yes') {
  if (!b || b.agent_status !== 'Success') {
    reasons.push(b?.error_code || 'agente_b_fallo');
    alerts.push('agent_b_failure');
  } else {
    if (b.agent_result?.routing_decision !== 'AUTO_CONTINUE') reasons.push(...(b.agent_result?.reasons ?? ['agente_b_revision_humana']));
    if (Number(b.agent_result?.confidence ?? 0) < minConfidence) reasons.push('agente_b_confianza_baja');
    if (b.latency_ms > maxLatency) alerts.push('agent_b_latency_threshold');
  }
} else {
  reasons.push('circuit_breaker:agente_b_no_ejecutado');
}

const totalCost = Number(a.estimated_cost_usd || 0) + Number(b?.estimated_cost_usd || 0);
const costConfigured = Boolean(a.cost_rate_configured || b?.cost_rate_configured);
if (costConfigured && totalCost > maxCost) {
  reasons.push('cost_budget_exceeded');
  alerts.push('cost_budget_exceeded');
}

const finalStatus = reasons.length === 0 ? 'AUTO_CONTINUE' : 'HUMAN_REVIEW';
const totalLatency = Date.now() - Number(s.execution_started_ms);

return [{
  json: {
    transaction_id: s.transaction_id,
    timestamp_sql: new Date().toISOString().slice(0,23).replace('T',' '),
    agent_name: 'Orchestrator',
    agent_status: 'Success',
    input_tokens: Number(a.input_tokens || 0) + Number(b?.input_tokens || 0),
    output_tokens: Number(a.output_tokens || 0) + Number(b?.output_tokens || 0),
    estimated_cost_usd: Number(totalCost.toFixed(8)),
    latency_ms: totalLatency,
    error_code: null,
    final_status: finalStatus,
    alert_required: alerts.length ? 'yes' : 'no',
    alert_reasons: [...new Set(alerts)],
    resultado: s.resultado_original,
    orchestration: {
      pattern: 'HANDOFF',
      agents_participated: b ? ['UIF_Analyst','UIF_Reviewer'] : ['UIF_Analyst'],
      max_agent_calls: s.config.max_agent_calls,
      min_agent_confidence: minConfidence,
      cost_rate_configured: costConfigured,
      reasons: [...new Set(reasons)],
      analyst: {
        status: a.agent_status,
        quality_score: a.agent_result?.quality_score ?? null,
        latency_ms: a.latency_ms
      },
      reviewer: b ? {
        status: b.agent_status,
        routing_decision: b.agent_result?.routing_decision ?? null,
        confidence: b.agent_result?.confidence ?? null,
        latency_ms: b.latency_ms
      } : null
    }
  }
}];

const x = $input.first().json;
const s = $('Sanitizar PII + Trace').first().json;
const reasons = Array.isArray(x.alert_reasons) ? x.alert_reasons : [];
const severe = reasons.some(r => ['agent_a_failure','agent_b_failure','cost_budget_exceeded'].includes(r));
return [{
  json: {
    url: s.config.alert_webhook_url,
    timestamp_sql: new Date().toISOString().slice(0,23).replace('T',' '),
    severity: severe ? 'HIGH' : 'MEDIUM',
    body: {
      event: 'UIF_AGENT_ALERT',
      transaction_id: x.transaction_id,
      status: x.final_status,
      reasons,
      latency_ms: x.latency_ms,
      estimated_cost_usd: x.estimated_cost_usd,
      timestamp: new Date().toISOString()
    }
  }
}];
